def decide_mouse_message(
    message: int,
    *,
    left_down_owned: bool = False,
    right_down_owned: bool = False,
) -> MouseDecision:
    """Return the demo action for one low-level mouse message."""

    if message == WM_LBUTTONDOWN:
        return MouseDecision(block=True, move_x_pixels=-MOVE_PIXELS)
    if message == WM_RBUTTONDOWN:
        return MouseDecision(block=True, move_x_pixels=MOVE_PIXELS)
    if message == WM_LBUTTONUP:
        return MouseDecision(block=left_down_owned)
    if message == WM_RBUTTONUP:
        return MouseDecision(block=right_down_owned)
    return MouseDecision(block=False)


